css:
.grid {
  display: grid;
  grid-template-rows: repeat(3, 44px);
  grid-auto-flow: column; /* fill down, then across */
  gap: 8px;
  padding: 12px;
  overflow-x: auto;
}

.cell {
  display: grid;
  place-items: center;
  width: 72px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}
